import MenuCard from "./MenuCard";

export default function MenuGrid({ menu, addToCart, removeFromCart, cart }) {
  return (
    <div className="menu-grid">
      {menu.map(item => {
        const cartItem = cart?.find(c => c.id === item.id);
        const quantity = cartItem?.quantity || 0;

        const isTopRated = Number(item.avg_rating) >= 4.5;
        const isPopular = Number(item.sold_count) >= 10; // adjust threshold if needed

        return (
          <div key={item.id} className="menu-card">

            {/* ✅ BADGES */}
            {(isTopRated || isPopular) && (
              <div className="menu-badges">
                {isTopRated && (
                  <span className="menu-badge top-rated">⭐ Top Rated</span>
                )}
                {isPopular && (
                  <span className="menu-badge popular">🔥 Popular</span>
                )}
              </div>
            )}

            {/* existing card UI */}
            <h3>{item.name}</h3>
            <p className="price">₹{item.price}</p>

            <p className="rating">
              ⭐ {item.avg_rating || 0} | Sold: {item.sold_count || 0}
            </p>

            <p className="stock">Stock: {item.stock}</p>

            {item.stock === 0 ? (
              <button className="btn unavailable" disabled>
                Unavailable
              </button>
            ) : quantity === 0 ? (
              <button
                className="btn add-btn"
                onClick={() => addToCart(item)}
              >
                ADD
              </button>
            ) : (
              <div className="qty-controls">
                <button onClick={() => removeFromCart(item.id)}>−</button>
                <span>{quantity}</span>
                <button onClick={() => addToCart(item)}>+</button>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}
